create extension if not exists pgcrypto;
create table admins(user_id uuid primary key references auth.users on delete cascade,role text not null default 'admin' check(role in('admin','editor')),created_at timestamptz default now());
create or replace function is_admin() returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from admins where user_id=auth.uid())$$;
create table services(id uuid primary key default gen_random_uuid(),name_ht text not null,name_es text not null,desc_ht text,desc_es text,image_url text,price_text text,active bool default true,sort int default 0,seo_title_ht text,seo_title_es text,seo_desc_ht text,seo_desc_es text,created_at timestamptz default now());
create table projects(id uuid primary key default gen_random_uuid(),service_id uuid references services on delete set null,title_ht text not null,title_es text not null,desc_ht text,desc_es text,country text check(country in('HT','DO')),public_location text,completed_on date,testimonial text,featured bool default false,status text default 'draft' check(status in('draft','published')),seo_title text,seo_desc text,created_at timestamptz default now());
create table project_media(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects on delete cascade,kind text not null check(kind in('before','after','photo','video')),path text not null,sort int default 0,created_at timestamptz default now());
create table inquiries(id uuid primary key default gen_random_uuid(),name text not null check(length(name)<=120),phone text not null check(length(phone)<=30),whatsapp text,email text,lang text check(lang in('ht','es')),subject text,message text not null check(length(message)<=3000),country text check(country in('HT','DO')),address jsonb default '{}',status text default 'new' check(status in('new','in_progress','resolved')),admin_notes text,created_at timestamptz default now());
create table appointments(id uuid primary key default gen_random_uuid(),service_id uuid references services,name text not null,phone text not null,email text,lang text,country text not null check(country in('HT','DO')),address jsonb default '{}',map_link text,lat double precision,lng double precision,description text,pref_date date not null,pref_time time not null,status text default 'new' check(status in('new','pending','confirmed','rescheduling','completed','cancelled')),admin_notes text,created_at timestamptz default now());
create unique index one_confirmed_slot on appointments(pref_date,pref_time) where status='confirmed';
create table quotes(id uuid primary key default gen_random_uuid(),service_id uuid references services,name text not null,phone text not null,email text,lang text,country text not null check(country in('HT','DO')),address jsonb default '{}',map_link text,lat double precision,lng double precision,description text not null,size_text text,start_date date,budget_text text,status text default 'new' check(status in('new','review','info_needed','prepared','accepted','declined','closed')),admin_notes text,created_at timestamptz default now());
create table reviews(id uuid primary key default gen_random_uuid(),project_id uuid references projects on delete set null,display_name text not null check(length(display_name)<=80),rating int not null check(rating between 1 and 5),body text check(length(body)<=2000),status text default 'pending' check(status in('pending','approved','rejected','hidden')),verified bool default false,admin_reply text,created_at timestamptz default now());
create table faqs(id uuid primary key default gen_random_uuid(),q_ht text,q_es text,a_ht text,a_es text,sort int default 0,active bool default true);
create table service_areas(id uuid primary key default gen_random_uuid(),country text not null check(country in('HT','DO')),name text not null,active bool default true);
create table site_settings(key text primary key,value jsonb not null);
do $$ declare t text; begin foreach t in array array['admins','services','projects','project_media','inquiries','appointments','quotes','reviews','faqs','service_areas','site_settings'] loop execute format('alter table %I enable row level security',t); execute format('create policy "admin all" on %I for all using(is_admin()) with check(is_admin())',t); end loop; end $$;
create policy "pub services" on services for select using(active);
create policy "pub projects" on projects for select using(status='published');
create policy "pub media" on project_media for select using(exists(select 1 from projects p where p.id=project_id and p.status='published'));
create policy "pub reviews" on reviews for select using(status='approved');
create policy "pub faqs" on faqs for select using(active);
create policy "pub areas" on service_areas for select using(active);
create policy "pub settings" on site_settings for select using(key not like 'private_%');
-- Formulaires publics: via Edge Function (validation, anti-spam, rate limit), aucun INSERT anonyme direct.
insert into storage.buckets(id,name,public) values('public-media','public-media',true) on conflict do nothing;
create policy "media read" on storage.objects for select using(bucket_id='public-media');
create policy "media admin write" on storage.objects for all using(bucket_id='public-media' and is_admin()) with check(bucket_id='public-media' and is_admin());
